package com.example.starter.consent;

import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 授权代次与记录的持久化访问，基于 JdbcTemplate，所有查询使用参数化 SQL。
 *
 * <p>用途为目录驱动的字符串代码；迁移后旧授权状态置为 MIGRATED，
 * 数据记录通过 {@link #rebindRecord} 一次性改绑到新用途（始终保持单一活动用途归属）。
 */
@Repository
public class ConsentRepository {

    private static final RowMapper<GrantRow> GRANT_MAPPER = (rs, rowNum) -> new GrantRow(
            rs.getString("subject_key"),
            rs.getString("purpose"),
            rs.getInt("epoch"),
            GrantStatus.valueOf(rs.getString("status")));

    private static final RowMapper<RecordRow> RECORD_MAPPER = (rs, rowNum) -> new RecordRow(
            rs.getString("subject_key"),
            rs.getString("purpose"),
            rs.getInt("epoch"),
            rs.getString("record_key"),
            rs.getString("payload"),
            rs.getString("attribute_value"));

    private final JdbcTemplate jdbc;

    public ConsentRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 授权代次行。
     *
     * @param subjectKey 主体标识
     * @param purpose    用途代码
     * @param epoch      代次，从 1 开始
     * @param status     状态：ACTIVE 有效 / REVOKED 已撤回 / MIGRATED 已迁移
     */
    public record GrantRow(String subjectKey, String purpose, int epoch, GrantStatus status) {
    }

    /**
     * 记录行。
     *
     * @param subjectKey     主体标识
     * @param purpose        当前活动用途代码
     * @param epoch          记录写入时所属授权代次（迁移不改写）
     * @param recordKey      记录键
     * @param payload        记录内容
     * @param attributeValue 记录属性取值，用于迁移目标判定，可为空
     */
    public record RecordRow(String subjectKey, String purpose, int epoch, String recordKey,
                            String payload, String attributeValue) {
    }

    Optional<GrantRow> findGrant(String subjectKey, String purpose, int epoch) {
        List<GrantRow> rows = jdbc.query(
                "SELECT subject_key, purpose, epoch, status FROM consent_grant"
                        + " WHERE subject_key = ? AND purpose = ? AND epoch = ?",
                GRANT_MAPPER, subjectKey, purpose, epoch);
        return rows.stream().findFirst();
    }

    Optional<GrantRow> findLatestGrant(String subjectKey, String purpose) {
        List<GrantRow> rows = jdbc.query(
                "SELECT subject_key, purpose, epoch, status FROM consent_grant"
                        + " WHERE subject_key = ? AND purpose = ? ORDER BY epoch DESC LIMIT 1",
                GRANT_MAPPER, subjectKey, purpose);
        return rows.stream().findFirst();
    }

    void insertGrant(String subjectKey, String purpose, int epoch, String requestId) {
        jdbc.update(
                "INSERT INTO consent_grant (subject_key, purpose, epoch, status, request_id)"
                        + " VALUES (?, ?, ?, 'ACTIVE', ?)",
                subjectKey, purpose, epoch, requestId);
    }

    /**
     * 仅当代次当前为 ACTIVE 时撤回；返回是否实际发生状态变更。
     */
    boolean revokeGrant(String subjectKey, String purpose, int epoch) {
        int updated = jdbc.update(
                "UPDATE consent_grant SET status = 'REVOKED', revoked_at = CURRENT_TIMESTAMP"
                        + " WHERE subject_key = ? AND purpose = ? AND epoch = ? AND status = 'ACTIVE'",
                subjectKey, purpose, epoch);
        return updated > 0;
    }

    /**
     * 迁移提交：仅当旧授权仍为 ACTIVE 时置为 MIGRATED；返回是否实际发生状态变更。
     */
    boolean markGrantMigrated(String subjectKey, String purpose, int epoch) {
        int updated = jdbc.update(
                "UPDATE consent_grant SET status = 'MIGRATED', migrated_at = CURRENT_TIMESTAMP"
                        + " WHERE subject_key = ? AND purpose = ? AND epoch = ? AND status = 'ACTIVE'",
                subjectKey, purpose, epoch);
        return updated > 0;
    }

    Optional<RecordRow> findRecord(String subjectKey, String purpose, int epoch, String recordKey) {
        List<RecordRow> rows = jdbc.query(
                "SELECT subject_key, purpose, epoch, record_key, payload, attribute_value"
                        + " FROM consent_record"
                        + " WHERE subject_key = ? AND purpose = ? AND epoch = ? AND record_key = ?",
                RECORD_MAPPER, subjectKey, purpose, epoch, recordKey);
        return rows.stream().findFirst();
    }

    void insertRecord(String subjectKey, String purpose, int epoch, String recordKey, String payload,
                      String attributeValue, String requestId) {
        jdbc.update(
                "INSERT INTO consent_record (subject_key, purpose, epoch, record_key, payload,"
                        + " attribute_value, request_id)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?)",
                subjectKey, purpose, epoch, recordKey, payload, attributeValue, requestId);
    }

    /**
     * 数据改绑：按主键把记录从旧用途改绑到新用途；条件含旧用途名，
     * 保证任何数据行始终只有一个活动用途归属，并发改绑由行锁串行化。
