        assertThat(resp.results().get(0).payload()).isEqualTo("pa");

        // 不能混读旧新用途：一批中夹带旧用途整批 422
        org.assertj.core.api.Assertions.assertThatThrownBy(() -> migrationService.batchQuery(
                new BatchQueryRequest(newToken.token(), List.of(
