        assertThat(e1.items()).hasSize(5);
        assertThat(e1.items().stream().filter(i -> i.itemType().equals("GRANT_ACTIVE"))).hasSize(4);
        assertThat(e1.items().stream().filter(i -> i.itemType().equals("RECORD")
